#!/usr/bin/env swift
//
// Renders the menu-bar template icon from the same square-blocked mark geometry as
// Scripts/make-icon.swift (website/assets/brand/codaset-symbol.svg), as black-on-transparent
// so AppKit's template-image tinting can recolor it for the menu bar.

import AppKit
import CoreGraphics
import Foundation

// Same 36x36 artboard geometry as make-icon.swift's markBlocks.
let markBlocks = [
    CGRect(x: 2, y: 2, width: 9, height: 9),
    CGRect(x: 14, y: 2, width: 8, height: 9),
    CGRect(x: 25, y: 2, width: 9, height: 9),
    CGRect(x: 2, y: 14, width: 9, height: 8),
    CGRect(x: 25, y: 14, width: 9, height: 8),
    CGRect(x: 2, y: 25, width: 9, height: 9),
    CGRect(x: 14, y: 25, width: 8, height: 9),
    CGRect(x: 25, y: 25, width: 9, height: 9),
]

func render(_ pixels: Int, to url: URL) {
    let S = CGFloat(pixels)
    let cs = CGColorSpace(name: CGColorSpace.sRGB)!
    guard let ctx = CGContext(
        data: nil, width: pixels, height: pixels, bitsPerComponent: 8, bytesPerRow: 0,
        space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
    ) else { fatalError("CGContext") }

    ctx.setAllowsAntialiasing(true)
    ctx.setShouldAntialias(true)
    ctx.interpolationQuality = .high

    ctx.translateBy(x: 0, y: S)
    ctx.scaleBy(x: 1, y: -1)

    // 36x36 native artboard scaled to fill this canvas edge-to-edge (menu bar glyphs run to
    // the template image's bounds; the surrounding whitespace is the status item's own padding).
    let scale = S / 36
    ctx.setFillColor(CGColor(gray: 0, alpha: 1))
    for block in markBlocks {
        ctx.fill(CGRect(
            x: block.minX * scale, y: block.minY * scale,
            width: block.width * scale, height: block.height * scale))
    }

    guard let cgImage = ctx.makeImage() else { fatalError("makeImage") }
    let rep = NSBitmapImageRep(cgImage: cgImage)
    guard let data = rep.representation(using: .png, properties: [:]) else {
        fatalError("PNG encode")
    }
    try! data.write(to: url)
    print("wrote \(url.path)")
}

let outDir = URL(fileURLWithPath: CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : ".")
render(18, to: outDir.appendingPathComponent("menubar_18.png"))
render(36, to: outDir.appendingPathComponent("menubar_18@2x.png"))

